#!/bin/zsh
TMUX=/opt/homebrew/bin/tmux
[ -x "$TMUX" ] || TMUX=/usr/local/bin/tmux
send() { $TMUX send-keys -t $1 C-u; sleep 1; $TMUX send-keys -t $1 "$2"; sleep 2; $TMUX send-keys -t $1 Enter; sleep 2; $TMUX send-keys -t $1 Enter; sleep 1; echo "sent -> $1"; }

send scribe3:1.1 "Your diagnosis reframes the whole programme and I had reported it wrong to V. Read and execute /Users/vinaybhardwaj/dev/_fable/orders/scribe3-clips.md. The line that matters: 2,513 of the 2,514 never-handled windows HAVE NO CLIP, and 2,142 of those are older than two days. The backlog is not waiting to be diarized, it is waiting to be clipped, and no amount of concurrency or closed-hours or Yoga touches that. Also worth stating plainly: pid 20557 used 0.32 seconds of CPU in two and a half hours and its log holds only the start event, so the night-drain has diarized NOTHING - every one of the 166 rows came from the app's own diarize_window job. Find what produces clip_r2_key, why it stopped, whether the source audio still exists for those windows, and what clipping 2,513 of them costs. Do not start a bulk run tonight - I want V deciding with a number in front of him."

